#!/usr/bin/env node
// Each client of hello against each server: the TypeScript, the C# and the Rust halves, each built
// with its messages generated by beadc and by its platform's own generator, thirty-six pairs. Each
// server writes its port and its gateway's on its first line, {"port":n,"gateway":m}, and serves
// until its input ends. A client calls it, then this asks its gateway, where it serves one, what a
// person asks with curl, and what the client writes, then a line for each of those answers, is
// transcript.txt, byte for byte; against a server without a gateway, its lines before the
// gateway's. Node alone, no dependency: run from anywhere once the three halves are built in both
// modes, the Rust half's binaries under its target folder, CARGO_TARGET_DIR's where it is set.
// HELLO_RUST, set to anything but `built`, leaves the Rust half's pairs out: sixteen pairs.
//
//   node examples/hello/pairs.mjs
//
// A pair passes when its client exits 0, what it wrote and its gateway's answers are
// transcript.txt, its server exits 0 once its input ends, the client writes nothing to its standard
// error and the server, where it serves a gateway, only the line of its nameless gateway call,
// nothing otherwise. A server that dies or hangs before its port, a client or a server that
// outlives its 30 s, fails its pair by name, and the run goes on. One line a pair, `ok` or
// `FAIL <client> client, <server> server: <what failed>`, what either wrote to its standard error
// indented under it; exit 1 when any failed.

import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

// ── Sides ─────────────────────────────────────────────────────────────────────

const HELLO = new URL('./', import.meta.url);

// ! bytes: every client writes LF on every platform, and the root's `eol=lf` keeps this file LF
const TRANSCRIPT = readFileSync(new URL('transcript.txt', HELLO));

// the document beadc wrote, which the gateway serves byte for byte
const DOCUMENT = readFileSync(new URL('gen/openapi.json', HELLO));

// what a person asks the gateway with curl, in this order, each its own exchange and its own Bead
// connection (decision 0037): a greeting; one given no name, whose command the gateway's connection
// answers SERVICE_UNKNOWN, so its resolver fails; a count past its rule and one within it, which
// the hook refuses first, since no exchange's connection was greeted; and the document
const ASKED = [
  ['POST', '/api/Hello/sayHello', '{"name":"Ada"}'],
  ['POST', '/api/Hello/sayHello', '{}'],
  ['POST', '/api/Hello/countDown', '{"from":11}'],
  ['POST', '/api/Hello/countDown', '{"from":3}'],
  ['GET', '/openapi.json'],
];

// ! what the server writes as the nameless call's resolver fails, by the router's error event: its
// gateway's second exchange, its connection's handle the in-memory transport's second
const GATEWAY_STDERR =
  'type=MEMORY;ip=127.0.0.1;ordinal=2: client protocol failure 18 SERVICE_UNKNOWN: no service 1\n';

// what a client writes, against a server without a gateway: transcript.txt's lines before the
// gateway's, which end it, a line for each of ASKED
const CLIENT_TRANSCRIPT = Buffer.from(
  `${TRANSCRIPT.toString('utf8')
    .split('\n')
    .slice(0, -1 - ASKED.length)
    .join('\n')}\n`,
  'utf8'
);

// what a server's start, a client's call, and a server's end once its input closed may each take
const LIMIT_MS = 30_000;

const TIMED_OUT = Symbol('timed out');

// whether the Rust half's pairs are played: unless HELLO_RUST says otherwise, where it is not built
const RUST = process.env.HELLO_RUST === undefined || process.env.HELLO_RUST === 'built';

// the Rust half's target folder: CARGO_TARGET_DIR where it is set, read from the Rust half's folder
// as cargo reads it there
const RUST_TARGET = resolve(
  fileURLToPath(new URL('rust/', HELLO)),
  process.env.CARGO_TARGET_DIR || 'target'
);

// the Rust binary of a mode, as cargo builds it: hello, its messages beadc's, and hello-external
const rustOf = (mode) => {
  const name = mode === 'generate' ? 'hello' : `hello-${mode}`;

  return resolve(RUST_TARGET, 'debug', process.platform === 'win32' ? `${name}.exe` : name);
};

// each half in each mode, as its build leaves it: its command, its arguments before its verb, and
// whether its server serves a gateway
const SIDES = new Map(
  ['generate', 'external'].flatMap((mode) => {
    return [
      [
        `TypeScript, ${mode}`,
        { command: 'node', path: [`typescript/dist/${mode}/hello.mjs`], gateway: true },
      ],
      [
        `C#, ${mode}`,
        { command: 'dotnet', path: [`dotnet/bin/${mode}/Debug/net10.0/Hello.dll`], gateway: true },
      ],
      ...(RUST ? [[`Rust, ${mode}`, { command: rustOf(mode), path: [], gateway: true }]] : []),
    ];
  })
);

// ── Processes ─────────────────────────────────────────────────────────────────

// `promise`, or TIMED_OUT once LIMIT_MS passed
const within = async (promise) => {
  let timer;
  const limit = new Promise((resolve) => {
    timer = setTimeout(resolve, LIMIT_MS, TIMED_OUT);
  });

  try {
    return await Promise.race([promise, limit]);
  } finally {
    clearTimeout(timer);
  }
};

// the side started with its verb, from hello's folder, its three streams piped and kept:
// `firstLine` its first line on the standard output, `ended` its exit, either undefined once it
// ended without
const start = (side, args) => {
  const { command, path } = SIDES.get(side);
  const child = spawn(command, [...path, ...args], { cwd: HELLO, stdio: ['pipe', 'pipe', 'pipe'] });
  const stdout = [];
  const stderr = [];
  const ended = new Promise((resolve) => {
    child.on('error', (error) => {
      resolve({ status: null, error });
    });
    child.on('close', (status, signal) => {
      resolve({ status, signal });
    });
  });
  const firstLine = new Promise((resolve) => {
    child.stdout.on('data', (chunk) => {
      stdout.push(chunk);

      const text = Buffer.concat(stdout).toString('utf8');
      const end = text.indexOf('\n');

      if (end !== -1) {
        resolve(text.slice(0, end).replace(/\r$/u, ''));
      }
    });
    void ended.then(() => {
      resolve(undefined);
    });
  });

  child.stderr.on('data', (chunk) => {
    stderr.push(chunk);
  });
  // ! a server that already died refuses the end of its input: its exit says why, not EPIPE
  child.stdin.on('error', () => {});

  return {
    child,
    ended,
    firstLine,
    stdout: () => {
      return Buffer.concat(stdout);
    },
    stderr: () => {
      return Buffer.concat(stderr).toString('utf8');
    },
  };
};

// how a process ended, in words
const endOf = ({ status, signal, error }) => {
  if (error !== undefined) {
    return `could not start: ${error.message}`;
  }

  return signal === null || signal === undefined ? `exit ${String(status)}` : `killed by ${signal}`;
};

// where `written` first parts from what was `owed`, in words
const differenceOf = (written, owed) => {
  const lines = written.toString('utf8').split('\n');
  const expected = owed.toString('utf8').split('\n');
  const at = expected.findIndex((line, index) => {
    return lines[index] !== line;
  });
  const index = at === -1 ? expected.length : at;

  return `line ${String(index + 1)} is ${JSON.stringify(lines[index] ?? '')}, transcript.txt's ${JSON.stringify(expected[index] ?? '')}`;
};

// ── Gateway ───────────────────────────────────────────────────────────────────

// the gateway on `port` asked each of ASKED, a line for each answer: its status, its type and its
// body, or, for the document, whether it is beadc's byte for byte
const gatewayLinesOf = async (port) => {
  const lines = [];

  for (const [method, path, body] of ASKED) {
    const response = await fetch(`http://127.0.0.1:${port}${path}`, {
      method,
      ...(body === undefined ? {} : { body, headers: { 'content-type': 'application/json' } }),
    });
    const content = Buffer.from(await response.arrayBuffer());
    const asked = body === undefined ? `${method} ${path}` : `${method} ${path} ${body}`;
    const answer =
      path === '/openapi.json'
        ? content.equals(DOCUMENT)
          ? "gen/openapi.json, beadc's, byte for byte"
          : `other than gen/openapi.json, ${String(content.length)} bytes`
        : content.toString('utf8');

    lines.push(
      `${asked}: ${String(response.status)} ${response.headers.get('content-type') ?? 'no type'}, ${answer}\n`
    );
  }

  return Buffer.from(lines.join(''), 'utf8');
};

// ── Pairs ─────────────────────────────────────────────────────────────────────

// the client's half of a pair, from the server's port to the client's end, its server's gateway
// asked where it serves one: what failed, whether the server's end is told already, whether it was
// called, and what the client wrote to its standard error
const callOn = async (serving, client, gateway) => {
  const line = await within(serving.firstLine);

  if (line === TIMED_OUT) {
    return {
      failed: [`the server wrote no port in ${String(LIMIT_MS / 1000)} s`],
      called: false,
      stderr: '',
    };
  }

  if (line === undefined) {
    return {
      failed: [`the server ended before its port, ${endOf(await serving.ended)}`],
      told: true,
      called: false,
      stderr: '',
    };
  }

  const form = gateway ? '{"port":n,"gateway":m}' : '{"port":n}';
  const [, port, gatewayPort] =
    (gateway ? /^\{"port":(\d+),"gateway":(\d+)\}$/u : /^\{"port":(\d+)\}$/u).exec(line) ?? [];

  if (port === undefined) {
    return {
      failed: [`the server's first line is ${JSON.stringify(line)}, not ${form}`],
      called: false,
      stderr: '',
    };
  }

  const failed = [];
  const calling = start(client, ['call', port]);
  const called = await within(calling.ended);

  if (called === TIMED_OUT) {
    calling.child.kill();
    await calling.ended;
    failed.push(`the client still ran after ${String(LIMIT_MS / 1000)} s`);
  } else if (called.status !== 0) {
    failed.push(`the client's ${endOf(called)}`);
  }

  let answered = Buffer.alloc(0);

  if (gateway) {
    try {
      answered = await gatewayLinesOf(gatewayPort);
    } catch (error) {
      failed.push(
        `the gateway could not be asked: ${error instanceof Error ? error.message : String(error)}`
      );
    }
  }

  const written = Buffer.concat([calling.stdout(), answered]);
  const owed = gateway ? TRANSCRIPT : CLIENT_TRANSCRIPT;

  if (!written.equals(owed)) {
    const what = gateway
      ? 'the client and the gateway wrote other than transcript.txt'
      : "the client wrote other than transcript.txt's lines before the gateway's";

    failed.push(`${what}, ${differenceOf(written, owed)}`);
  }

  if (calling.stderr() !== '') {
    failed.push('the client wrote to its standard error');
  }

  return { failed, called: true, stderr: calling.stderr() };
};

// what `client` against `server` failed, none when the pair passes, and what each wrote to its
// standard error
const pair = async (server, client) => {
  const { gateway } = SIDES.get(server);
  const serving = start(server, ['serve']);
  const { failed, told = false, called, stderr } = await callOn(serving, client, gateway);

  serving.child.stdin.end();

  const served = await within(serving.ended);

  if (served === TIMED_OUT) {
    serving.child.kill();
    await serving.ended;
    failed.push(`the server still ran ${String(LIMIT_MS / 1000)} s after its input ended`);
  } else if (served.status !== 0 && !told) {
    failed.push(`the server's ${endOf(served)} once its input ended`);
  }

  // a server never called, or without a gateway, writes no gateway line: the first's failure is
  // its port's, said above
  if (called && gateway ? serving.stderr() !== GATEWAY_STDERR : serving.stderr() !== '') {
    failed.push(
      gateway
        ? "the server wrote to its standard error other than its nameless gateway call's line"
        : 'the server wrote to its standard error'
    );
  }

  return {
    failed,
    streams: [
      ['client', stderr],
      ['server', serving.stderr()],
    ],
  };
};

// ── Main ──────────────────────────────────────────────────────────────────────

let failures = 0;

if (!RUST) {
  console.log(
    `the Rust half's pairs left out: HELLO_RUST is ${JSON.stringify(process.env.HELLO_RUST)}`
  );
}

for (const server of SIDES.keys()) {
  for (const client of SIDES.keys()) {
    const { failed, streams } = await pair(server, client);

    if (failed.length === 0) {
      console.log(`ok   ${client} client, ${server} server`);
    } else {
      failures += 1;
      console.log(`FAIL ${client} client, ${server} server: ${failed.join('; ')}`);

      // what each wrote to its standard error, indented under its pair
      for (const [who, text] of streams) {
        if (text !== '') {
          console.log(`  the ${who}'s standard error:`);
          console.log(text.trimEnd().replace(/^/gmu, '    '));
        }
      }
    }
  }
}

process.exit(failures === 0 ? 0 : 1);
